import boto3
from datetime import datetime, timedelta

def compare_metrics(metric_name, namespace, dimension_name, value1, value2, duration_minutes=60, region='us-east-1'):
    client = boto3.client('cloudwatch', region_name=region)
    end_time = datetime.utcnow()
    start_time = end_time - timedelta(minutes=duration_minutes)
    period = 300  # 5 minutes

    query1 = {
        'Id': 'q1',
        'MetricStat': {
            'Metric': {
                'Namespace': namespace,
                'MetricName': metric_name,
                'Dimensions': [{'Name': dimension_name, 'Value': value1}]
            },
            'Period': period,
            'Stat': 'Average'
        }
    }
    query2 = {
        'Id': 'q2',
        'MetricStat': {
            'Metric': {
                'Namespace': namespace,
                'MetricName': metric_name,
                'Dimensions': [{'Name': dimension_name, 'Value': value2}]
            },
            'Period': period,
            'Stat': 'Average'
        }
    }

    response = client.get_metric_data(
        MetricDataQueries=[query1, query2],
        StartTime=start_time,
        EndTime=end_time
    )

    results = {r['Id']: r for r in response['MetricDataResults']}
    val1 = results['q1']['Values'][-1] if results['q1']['Values'] else None
    val2 = results['q2']['Values'][-1] if results['q2']['Values'] else None
    difference = val1 - val2 if val1 is not None and val2 is not None else None

    return {
        'resource1': value1,
        'value1': val1,
        'resource2': value2,
        'value2': val2,
        'difference': difference
    }
